import ReportsPage from "./pages/ReportsPage";
import ScriptsPage from "./pages/ScriptsPage";

type RouteKey = "console" | "dashboard" | "market" | "scripts" | "reports" | "assets";

interface RouteItem {
  key: RouteKey;
  label: string;
  eyebrow: string;
  description: string;
}

const ROUTES: RouteItem[] = [
  {
    key: "console",
    label: "Console",
    eyebrow: "LIVE",
    description: "直播控制台",
  },
  {
    key: "dashboard",
    label: "Dashboard",
    eyebrow: "DATA",
    description: "经营数据看板",
  },
  {
    key: "market",
    label: "Market",
    eyebrow: "OPS",
    description: "市场与商品池",
  },
  {
    key: "scripts",
    label: "Scripts",
    eyebrow: "COPY",
    description: "话术工作台",
  },
  {
    key: "reports",
    label: "Reports",
    eyebrow: "RECAP",
    description: "播后复盘",
  },
  {
    key: "assets",
    label: "Assets",
    eyebrow: "MEDIA",
    description: "素材资产库",
  },
];

const ROUTE_KEYS = new Set<RouteKey>(ROUTES.map((route) => route.key));

function isRouteKey(value: string): value is RouteKey {
  return ROUTE_KEYS.has(value as RouteKey);
}

function getInitialRoute(): RouteKey {
  const hashRoute = window.location.hash.replace("#", "");

  if (isRouteKey(hashRoute)) {
    return hashRoute;
  }

  return "console";
}

function App() {
  const [activeRoute, setActiveRoute] = useState<RouteKey>(getInitialRoute);

  useEffect(() => {
    const handleHashChange = () => {
      const nextRoute = window.location.hash.replace("#", "");

      if (isRouteKey(nextRoute)) {
        setActiveRoute(nextRoute);
      }
    };

    window.addEventListener("hashchange", handleHashChange);

    return () => {
      window.removeEventListener("hashchange", handleHashChange);
    };
  }, []);

  const currentRoute = useMemo(
    () => ROUTES.find((route) => route.key === activeRoute) ?? ROUTES[0],
    [activeRoute],
  );

  const handleRouteChange = (route: RouteKey) => {
    setActiveRoute(route);

    if (window.location.hash !== `#${route}`) {
      window.history.replaceState(null, "", `#${route}`);
    }
  };

  const page = useMemo(() => {
    switch (activeRoute) {
      case "dashboard":
        return <DashboardPage />;
      case "market":
        return <MarketPage />;
      case "scripts":
        return <ScriptsPage />;
      case "reports":
        return <ReportsPage />;
      case "assets":
        return <AssetsPage />;
      case "console":
      default:
        return <ConsolePage />;
    }
  }, [activeRoute]);

  return (
    <div className="phs-shell flex min-h-screen bg-[var(--bg-page)] text-[var(--text-body)]">
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-[var(--sidebar-width)] border-r border-[var(--border)] bg-[var(--bg-deep)]/95 px-4 py-5 backdrop-blur-xl lg:flex lg:flex-col">
        <div className="mb-8 flex items-center gap-3 px-2">
          <div className="flex h-10 w-10 items-center justify-center rounded-[12px] border border-[var(--border-strong)] bg-[oklch(13%_0.008_95)] shadow-[0_0_40px_oklch(84%_0.19_80_/_0.14)]">
            <span className="text-[16px] font-semibold tracking-[-0.04em] text-[var(--accent)]">
              P
            </span>
          </div>

          <div className="min-w-0">
            <div className="text-[16px] font-semibold leading-tight text-[var(--text-primary)]">
              PHS Studio
            </div>
            <div className="mt-0.5 text-[12px] leading-tight text-[var(--text-muted)]">
              Live commerce system
            </div>
          </div>
        </div>

        <nav className="flex flex-1 flex-col gap-1.5" aria-label="PHS navigation">
          {ROUTES.map((route) => {
            const active = route.key === activeRoute;

            return (
              <button
                key={route.key}
                type="button"
                onClick={() => handleRouteChange(route.key)}
                aria-current={active ? "page" : undefined}
                className={[
                  "group relative flex w-full items-center gap-3 rounded-[8px] border px-3 py-3 text-left transition-all duration-300 ease-impeccable",
                  active
                    ? "border-[oklch(84%_0.19_80_/_0.36)] bg-[oklch(84%_0.19_80_/_0.105)] text-[var(--text-primary)] shadow-[0_12px_34px_oklch(84%_0.19_80_/_0.1)]"
                    : "border-transparent bg-transparent text-[var(--text-muted)] hover:border-[var(--border)] hover:bg-[oklch(91%_0_0_/_0.045)] hover:text-[var(--text-body)]",
                ].join(" ")}
              >
                <span
                  className={[
                    "absolute left-0 top-1/2 h-7 w-[2px] -translate-y-1/2 rounded-full transition-all duration-300 ease-impeccable",
                    active
                      ? "bg-[var(--accent)] opacity-100 shadow-[0_0_18px_oklch(84%_0.19_80_/_0.58)]"
                      : "bg-transparent opacity-0",
                  ].join(" ")}
                />

                <span
                  className={[
                    "flex h-9 w-9 shrink-0 items-center justify-center rounded-[8px] border text-[12px] font-semibold tracking-[0.08em] transition-all duration-300 ease-impeccable",
                    active
                      ? "border-[oklch(84%_0.19_80_/_0.38)] bg-[oklch(84%_0.19_80_/_0.14)] text-[var(--accent)]"
                      : "border-[var(--border)] bg-[oklch(11%_0.006_95)] text-[var(--text-muted)] group-hover:border-[var(--border-strong)] group-hover:text-[var(--accent-hover)]",
                  ].join(" ")}
                >
                  {route.eyebrow}
                </span>

                <span className="min-w-0">
                  <span className="block text-[14px] font-semibold leading-tight">
                    {route.label}
