              </button>
            );
          })}
        </nav>

        <div className="mt-6 rounded-[16px] border border-[var(--border)] bg-[oklch(11%_0.006_95)] p-4">
          <div className="text-[12px] font-semibold uppercase tracking-[0.14em] text-[var(--accent)]">
