              <span className="h-2 w-2 rounded-full bg-[var(--success)] shadow-[0_0_18px_oklch(45%_0.18_145_/_0.58)]" />
              <span className="text-[12px] font-medium text-[var(--text-muted)]">
                Runtime ready
              </span>
            </div>
          </div>
