import type { CSSProperties } from "react";

export type StatusKind =
  | "idle"
  | "running"
  | "success"
  | "warning"
  | "danger"
  | "error"
  | "offline"
  | "online";

export interface StatusLightProps {
  status?: StatusKind;
  label?: string;
  showLabel?: boolean;
  size?: "sm" | "md" | "lg";
  pulse?: boolean;
  className?: string;
}

interface StatusTone {
  color: string;
  glow: string;
  text: string;
  label: string;
}

const STATUS_TONES: Record<StatusKind, StatusTone> = {
  idle: {
    color: "oklch(72% 0 0)",
    glow: "oklch(72% 0 0 / 0.32)",
    text: "var(--text-muted)",
    label: "Idle",
  },
  running: {
    color: "var(--accent)",
    glow: "oklch(84% 0.19 80 / 0.48)",
    text: "var(--accent)",
    label: "Running",
  },
  success: {
    color: "var(--success)",
    glow: "oklch(45% 0.18 145 / 0.5)",
    text: "oklch(70% 0.16 145)",
    label: "Success",
  },
  warning: {
    color: "var(--warning)",
    glow: "oklch(78% 0.14 74 / 0.48)",
    text: "var(--warning)",
    label: "Warning",
  },
  danger: {
    color: "var(--danger)",
    glow: "oklch(58% 0.15 35 / 0.48)",
    text: "oklch(72% 0.13 35)",
    label: "Danger",
  },
  error: {
    color: "var(--danger)",
    glow: "oklch(58% 0.15 35 / 0.48)",
    text: "oklch(72% 0.13 35)",
    label: "Error",
  },
  offline: {
    color: "oklch(42% 0 0)",
    glow: "oklch(42% 0 0 / 0.24)",
    text: "var(--text-muted)",
    label: "Offline",
  },
  online: {
    color: "var(--success)",
    glow: "oklch(45% 0.18 145 / 0.5)",
    text: "oklch(70% 0.16 145)",
    label: "Online",
  },
};

const SIZE_CLASS: Record<NonNullable<StatusLightProps["size"]>, string> = {
  sm: "h-2 w-2",
  md: "h-2.5 w-2.5",
  lg: "h-3 w-3",
};

function buildStyle(tone: StatusTone): CSSProperties {
  return {
    "--status-color": tone.color,
    "--status-glow": tone.glow,
    "--status-text": tone.text,
  } as CSSProperties;
}

export default function StatusLight({
  status = "idle",
  label,
  showLabel = false,
  size = "md",
  pulse,
  className = "",
}: StatusLightProps) {
  const tone = STATUS_TONES[status];
  const resolvedLabel = label ?? tone.label;
  const shouldPulse = pulse ?? status === "running";

  return (
    <span
      className={[
        "inline-flex items-center gap-2 align-middle",
        className,
      ].join(" ")}
      style={buildStyle(tone)}
      aria-label={resolvedLabel}
      title={resolvedLabel}
    >
      <span className="relative inline-flex items-center justify-center">
        {shouldPulse ? (
          <span
            className={[
              "absolute rounded-full bg-[var(--status-color)] opacity-30",
              SIZE_CLASS[size],
              "animate-[statusPulse_1600ms_cubic-bezier(0.16,1,0.3,1)_infinite]",
            ].join(" ")}
          />
        ) : null}

        <span
          className={[
            "relative rounded-full bg-[var(--status-color)] shadow-[0_0_18px_var(--status-glow)]",
            SIZE_CLASS[size],
          ].join(" ")}
        />
      </span>

      {showLabel ? (
        <span className="text-[12px] font-medium leading-none text-[var(--status-text)]">
          {resolvedLabel}
        </span>
      ) : null}
    </span>
  );
}
