import type { CSSProperties, KeyboardEvent, ReactNode } from "react";
import StatusLight, { type StatusKind } from "../StatusLight";

export type PipelineStepStatus =
  | "idle"
  | "running"
  | "success"
  | "warning"
  | "error"
  | "danger"
  | "blocked"
  | "online"
  | "offline";

export interface PipelineMetric {
  label: string;
  value: string | number;
  hint?: string;
}

export interface PipelineStep {
  id?: string;
  title?: string;
  name?: string;
  description?: string;
  status?: PipelineStepStatus;
  statusLabel?: string;
  progress?: number;
  duration?: string;
  meta?: string;
  metrics?: PipelineMetric[];
}

export interface PipelineStepCardProps {
  step?: PipelineStep;
  index?: number;
  title?: string;
  name?: string;
  description?: string;
  status?: PipelineStepStatus;
  statusLabel?: string;
  progress?: number;
  duration?: string;
  meta?: string;
  metrics?: PipelineMetric[];
  active?: boolean;
  selected?: boolean;
  disabled?: boolean;
  actionLabel?: string;
  onAction?: () => void;
  onClick?: () => void;
  children?: ReactNode;
  className?: string;
}

function clampProgress(value: number | undefined): number {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return 0;
  }

  return Math.min(100, Math.max(0, value));
}

function toStatusKind(status: PipelineStepStatus): StatusKind {
  if (status === "blocked") {
    return "warning";
  }

  if (status === "danger") {
    return "danger";
  }

  return status;
}

function getStatusLabel(status: PipelineStepStatus): string {
  const labels: Record<PipelineStepStatus, string> = {
    idle: "Idle",
    running: "Running",
    success: "Success",
    warning: "Warning",
    error: "Error",
    danger: "Danger",
    blocked: "Blocked",
    online: "Online",
    offline: "Offline",
  };

  return labels[status];
}

function getProgressTrackStyle(progress: number): CSSProperties {
  return {
    width: `${progress}%`,
  };
}

export default function PipelineStepCard({
  step,
  index,
  title,
  name,
  description,
  status,
  statusLabel,
  progress,
  duration,
  meta,
  metrics,
  active = false,
  selected = false,
  disabled = false,
  actionLabel,
  onAction,
  onClick,
  children,
  className = "",
}: PipelineStepCardProps) {
  const resolvedTitle = title ?? name ?? step?.title ?? step?.name ?? "未命名步骤";
  const resolvedDescription = description ?? step?.description;
  const resolvedStatus = status ?? step?.status ?? "idle";
  const resolvedStatusLabel =
    statusLabel ?? step?.statusLabel ?? getStatusLabel(resolvedStatus);
  const resolvedProgress = clampProgress(progress ?? step?.progress);
  const resolvedDuration = duration ?? step?.duration;
  const resolvedMeta = meta ?? step?.meta;
  const resolvedMetrics = metrics ?? step?.metrics ?? [];
  const stepNumber =
    typeof index === "number" ? String(index + 1).padStart(2, "0") : "—";
  const highlighted = active || selected;
  const interactive = typeof onClick === "function" && !disabled;

  const handleKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (!interactive) {
      return;
    }

    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onClick?.();
    }
  };

  return (
    <article
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      aria-disabled={disabled || undefined}
      onClick={interactive ? onClick : undefined}
      onKeyDown={handleKeyDown}
      className={[
        "group relative overflow-hidden rounded-[16px] border bg-[var(--bg-raised)] p-5 transition-all duration-300 ease-impeccable",
        "shadow-[0_1px_0_oklch(91%_0_0_/_0.035)_inset,0_24px_80px_oklch(3%_0.004_95_/_0.38)]",
        highlighted
          ? "border-[var(--border-strong)] shadow-[0_1px_0_oklch(91%_0_0_/_0.05)_inset,0_28px_90px_oklch(84%_0.19_80_/_0.12)]"
          : "border-[var(--border)] hover:border-[oklch(74%_0.09_82_/_0.42)]",
        interactive ? "cursor-pointer hover:-translate-y-0.5" : "",
        disabled ? "pointer-events-none opacity-55" : "",
        className,
      ].join(" ")}
    >
      <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,oklch(84%_0.19_80_/_0.72),transparent)] opacity-70" />

      {highlighted ? (
        <div className="pointer-events-none absolute right-4 top-4 h-16 w-16 rounded-full bg-[oklch(84%_0.19_80_/_0.08)] blur-2xl" />
      ) : null}

      <div className="relative flex items-start justify-between gap-4">
        <div className="flex min-w-0 items-start gap-4">
          <div
            className={[
              "flex h-10 w-10 shrink-0 items-center justify-center rounded-[10px] border text-[14px] font-semibold tracking-[-0.02em] transition-all duration-300 ease-impeccable",
              highlighted
                ? "border-[oklch(84%_0.19_80_/_0.48)] bg-[oklch(84%_0.19_80_/_0.13)] text-[var(--accent)]"
                : "border-[var(--border)] bg-[oklch(9%_0.005_95)] text-[var(--text-muted)] group-hover:border-[var(--border-strong)] group-hover:text-[var(--accent-hover)]",
            ].join(" ")}
          >
            {stepNumber}
          </div>

          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="truncate text-[16px] font-semibold leading-[1.4] text-[var(--text-primary)]">
                {resolvedTitle}
              </h3>

              <StatusLight
                status={toStatusKind(resolvedStatus)}
                label={resolvedStatusLabel}
                showLabel
                pulse={resolvedStatus === "running"}
                size="sm"
              />
            </div>

            {resolvedDescription ? (
              <p className="mt-2 max-w-[64ch] text-[14px] leading-[1.6] text-[var(--text-muted)]">
                {resolvedDescription}
              </p>
            ) : null}
          </div>
        </div>

        {onAction ? (
          <button
            type="button"
            onClick={(event) => {
              event.stopPropagation();
              onAction();
            }}
            disabled={disabled}
            className="shrink-0 rounded-[8px] border border-[var(--border)] bg-[oklch(13%_0.006_95)] px-3 py-2 text-[12px] font-semibold text-[var(--text-body)] transition-all duration-300 ease-impeccable hover:border-[var(--border-strong)] hover:bg-[oklch(16%_0.008_95)] hover:text-[var(--accent-hover)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {actionLabel ?? "查看"}
          </button>
        ) : null}
      </div>

      {(resolvedMeta || resolvedDuration) ? (
        <div className="relative mt-4 flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-[var(--border)] pt-4">
          {resolvedMeta ? (
            <span className="text-[12px] font-medium text-[var(--text-muted)]">
              {resolvedMeta}
            </span>
          ) : null}

          {resolvedDuration ? (
            <span className="text-[12px] font-medium text-[var(--text-muted)]">
              耗时 {resolvedDuration}
            </span>
          ) : null}
        </div>
      ) : null}

      {resolvedProgress > 0 || resolvedStatus === "running" ? (
        <div className="relative mt-5">
          <div className="mb-2 flex items-center justify-between gap-3">
            <span className="text-[12px] font-medium text-[var(--text-muted)]">
              Progress
            </span>
            <span className="text-[12px] font-semibold text-[var(--accent)]">
              {resolvedProgress}%
            </span>
          </div>

          <div className="h-1.5 overflow-hidden rounded-full bg-[oklch(91%_0_0_/_0.08)]">
            <div
              className="h-full rounded-full bg-[linear-gradient(90deg,var(--accent-active),var(--accent))] shadow-[0_0_18px_oklch(84%_0.19_80_/_0.32)] transition-[width] duration-500 ease-impeccable"
              style={getProgressTrackStyle(resolvedProgress)}
            />
          </div>
        </div>
      ) : null}

      {resolvedMetrics.length > 0 ? (
        <dl className="relative mt-5 grid gap-4 border-t border-[var(--border)] pt-4 sm:grid-cols-3">
          {resolvedMetrics.map((metric) => (
            <div key={`${metric.label}-${metric.value}`} className="min-w-0">
              <dt className="truncate text-[12px] font-medium text-[var(--text-muted)]">
                {metric.label}
              </dt>
              <dd className="mt-1 truncate text-[20px] font-semibold leading-[1.3] text-[var(--text-primary)]">
                {metric.value}
              </dd>
              {metric.hint ? (
                <dd className="mt-1 truncate text-[12px] text-[var(--text-muted)]">
                  {metric.hint}
                </dd>
              ) : null}
            </div>
          ))}
        </dl>
      ) : null}

      {children ? (
        <div className="relative mt-5 border-t border-[var(--border)] pt-4 text-[14px] leading-[1.6] text-[var(--text-body)]">
          {children}
        </div>
      ) : null}
    </article>
  );
}

